script:
frappe.ui.form.on('Customer', {
    refresh: function(frm) {
        format_customer_id(frm);
    },
    
    onload: function(frm) {
        format_customer_id(frm);
    },
    
    custom_customer_id: function(frm) {
        format_customer_id(frm);
    }
});

function format_customer_id(frm) {
    setTimeout(function() {
        const customer_id = frm.doc.custom_customer_id;
        
        if (!customer_id) {
            return;
        }
        
        // Debug: Find where these fields are
        console.log('=== Debugging duplicate fields ===');
        $('[data-fieldname="custom_customer_id"]').each(function(index) {
            const wrapper = $(this);
            console.log(`Field ${index + 1}:`, {
                'parent_section': wrapper.closest('[data-fieldname]').parent().attr('data-fieldname'),
                'in_tab': wrapper.closest('.form-tab').attr('data-tab-id'),
                'visible': wrapper.is(':visible'),
                'offset_top': wrapper.offset()?.top,
                'html_preview': wrapper.html().substring(0, 150)
            });
        });
        
        // Determine gender and color
        let color, bg_color;
        if (customer_id.startsWith('F-')) {
            color = '#C2185B';  // Pink/Magenta for Female
            bg_color = '#FCE4EC';  // Light pink background
        } else if (customer_id.startsWith('M-')) {
            color = '#1976D2';  // Blue for Male
            bg_color = '#E3F2FD';  // Light blue background
        } else {
            color = '#757575';  // Gray for unknown
            bg_color = '#F5F5F5';  // Light gray background
        }
        
        // Find ALL instances of the custom_customer_id field and style them
        $('[data-fieldname="custom_customer_id"]').each(function() {
            const wrapper = $(this);
            
            // Hide the label
            wrapper.find('.control-label').hide();
            wrapper.find('.clearfix').hide();
            
            // Style for read mode
            wrapper.find('.control-value').css({
                'font-size': '14px',
                'font-weight': '600',
                'color': color,
                'background-color': bg_color,
                'padding': '6px 12px',
                'border-radius': '4px',
                'border': '1px solid ' + color,
                'text-align': 'center',
                'letter-spacing': '0.5px',
                'font-family': 'monospace',
                'display': 'inline-block',
                'min-width': '100px'
            });
            
            // Style for edit mode
            wrapper.find('input').css({
                'font-size': '14px',
                'font-weight': '600',
                'color': color,
                'background-color': bg_color,
                'padding': '6px 12px',
                'border-radius': '4px',
                'border': '1px solid ' + color,
                'text-align': 'center',
                'letter-spacing': '0.5px',
                'font-family': 'monospace'
            });
        });
    }, 100);
}
